"""Flatten a Multilevel Doubly Linked List — iterative DFS with a stack.

When a node has a child, its `next` is parked on the stack and the child chain
is spliced in; the stack is popped whenever a chain runs out.

Time: O(n)   Space: O(depth)
"""
if "Node" not in globals():
    class Node:
        def __init__(self, val=0, prev=None, next=None, child=None):
            self.val = val
            self.prev = prev
            self.next = next
            self.child = child


class Solution:
    def flatten(self, head):
        if not head:
            return None
        stack, node = [], head
        while node:
            if getattr(node, "child", None):
                if node.next:
                    stack.append(node.next)
                node.next = node.child
                node.child.prev = node
                node.child = None
            if not node.next and stack:
                nxt = stack.pop()
                node.next = nxt
                nxt.prev = node
            node = node.next
        return head
